-- Темы 09–13: исправлены странности в 24 вопросах (46 исправлений), прежние версии в question_archive (миграция 115), ключи не меняются.
-- Источник: scripts/questions/116_oddities_topics09_13.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Допишите команду, чтобы создать таблицу, изменения которой не пишутся в журнал предзаписи и которая доступна другим сеансам этой базы:
```
CREATE ___ TABLE t (id int);
```', NULL, NULL, NULL, 'Допишите команду создания таблицы без WAL-журналирования её данных, доступной другим сеансам этой базы при наличии прав:
```
CREATE ___ TABLE t (id int);
```'),
        ('question', 'Допишите команду, чтобы длинные значения выносились в TOAST без сжатия:
```
ALTER TABLE t ALTER COLUMN body SET STORAGE ___;
```', NULL, NULL, NULL, 'Допишите команду, чтобы для столбца body типа text разрешить вынос новых значений в TOAST, но не пытаться их сжимать:
```
ALTER TABLE t ALTER COLUMN body SET STORAGE ___;
```'),
        ('question', 'Допишите команду перед установкой расширения pg_stat_statements (список shared_preload_libraries пока пуст; после команды нужен перезапуск сервера):
```
ALTER SYSTEM SET shared_preload_libraries = ___;
```', NULL, NULL, NULL, 'Допишите команду, чтобы при старте сервера загрузить модуль, накапливающий число выполнений и время по нормализованным SQL-запросам. Список shared_preload_libraries пока пуст, после команды нужен перезапуск:
```
ALTER SYSTEM SET shared_preload_libraries = ___;
```'),
        ('question', 'Как объекты хранятся внутри каталога табличного пространства?', NULL, NULL, NULL, 'Как PostgreSQL хранит файлы обычных таблиц и их индексов в одном табличном пространстве?'),
        ('question', 'Как называется первый файл основного слоя постоянной таблицы?', NULL, NULL, NULL, 'Как называется первый сегмент основного слоя обычной журналируемой таблицы?'),
        ('question', 'Значение уже вынесено в TOAST. UPDATE изменяет другой столбец, не затрагивая столбец с вынесенным значением. Что происходит в toast-таблице?', NULL, NULL, NULL, 'Значение уже вынесено в TOAST. UPDATE изменяет другой столбец, не затрагивая вынесенное значение; параметры хранения не менялись. Что происходит с вынесенным значением?'),
        ('question', 'Сервер собран с поддержкой lz4. Допишите команду, задающую lz4 как метод сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```', NULL, NULL, NULL, 'Сервер собран с поддержкой lz4. Допишите имя параметра, чтобы задать lz4 методом сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```'),
        ('question', 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Допишите маску имени файла, чтобы при ротации раз в час и log_truncate_on_rotation = on получалось 24 файла в сутки:
```
log_filename = ''postgresql-___.log''
```', NULL, NULL, NULL, 'Коллектор сообщений включён, log_destination = ''stderr'', ротация раз в час, log_truncate_on_rotation = on. Допишите маску для суточного цикла из 24 повторяющихся имён файлов:
```
log_filename = ''postgresql-___.log''
```'),
        ('question', 'Почему недостаточно один раз отозвать у public привилегию EXECUTE на все подпрограммы?', NULL, NULL, NULL, 'Привилегии по умолчанию для новых подпрограмм не меняли. Почему недостаточно один раз отозвать у PUBLIC EXECUTE на все существующие подпрограммы?'),
        ('option', 'Чем information_schema отличается от pg_catalog?', 'Обновляется с задержкой после изменений каталога', NULL, 'Это представления над pg_catalog, они всегда показывают текущее состояние каталога.', 'Это представления над pg_catalog, без отдельного обновления с задержкой. Видимость строк определяется снимком запроса; на Repeatable Read изменения других транзакций после создания снимка могут быть не видны.'),
        ('option', 'Для чего служат табличные пространства?', 'Логически группируют объекты, как схемы', 'Логически группируют таблицы внутри каждой базы', 'Логическое разделение — это схемы.', 'Логическую группировку обеспечивают схемы.'),
        ('option', 'Для чего служат табличные пространства?', 'Ограничивают права пользователей на объекты', 'Разграничивают права ролей на таблицы и индексы', 'Права на сами таблицы задаются привилегиями. У табличного пространства есть своя привилегия CREATE: она разрешает размещать в нём объекты, но не даёт доступа к данным.', 'Привилегии на таблицы и индексы задаются отдельно от их размещения. У табличного пространства есть своя привилегия CREATE: она разрешает размещать в нём объекты, но не даёт доступа к данным.'),
        ('option', 'Для чего служат табличные пространства?', 'Разделяют базы данных по кодировке символов', 'Задают общую кодировку для размещённых таблиц', NULL, NULL),
        ('option', 'Для чего служат табличные пространства?', 'Задают, в каком каталоге лежат файлы данных', 'Размещают файлы данных в выбранном каталоге', 'Табличное пространство определяет физическое расположение данных в файловой системе: по сути это указание на каталог.', 'Табличное пространство задаёт каталог для файлов данных: по сути это указание на каталог в файловой системе.'),
        ('option', 'Зачем внутри каталога пользовательского ТП есть подкаталог с версией сервера?', 'Для удобного перехода на другую версию сервера', 'Для разделения файлов разных версий', 'Старая и новая версии могут временно жить в одном каталоге, например при pg_upgrade.', 'Подкаталоги разделяют файлы версий, позволяя использовать один LOCATION без конфликтов, например при pg_upgrade.'),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Для отношений с нежурналируемым хранением', 'Для нежурналируемых отношений', 'Слой init есть у нежурналируемых таблиц, их индексов и последовательностей. После аварийного восстановления таблица пуста, последовательность возвращается к начальному состоянию.', 'Слой init есть у нежурналируемых таблиц, их индексов и последовательностей; после аварии он записывается на место основного слоя, поэтому таблица пуста, а последовательность в начальном состоянии.'),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Для индексов журналируемых таблиц', NULL, 'Слой init есть не только у индексов журналируемых таблиц: он есть у нежурналируемых таблиц, их индексов и последовательностей.', 'У индексов журналируемых таблиц слоя init нет; он есть у индексов нежурналируемых таблиц.'),
        ('explanation', 'Какое представление показывает текущую активность обслуживающих и фоновых процессов?', NULL, NULL, 'Его работа зависит от параметра track_activities, включённого по умолчанию.', 'Даже при track_activities = off представление сохраняет строки процессов и такие сведения, как pid и backend_type; состояние сеанса с отключённым отслеживанием отображается как disabled, текст запроса не отслеживается.'),
        ('option', 'За ходом какой команды позволяет следить представление pg_stat_progress_vacuum?', 'VACUUM, включая автоочистку', 'VACUUM без FULL и автоочистка', 'Обычный VACUUM и процессы автоочистки.', 'Обычный VACUUM, включая автоочистку; VACUUM FULL отслеживается через pg_stat_progress_cluster.'),
        ('option', 'Какой парольный метод аутентификации рекомендуется использовать?', 'Метод password из pg_hba.conf', NULL, 'Передаёт пароль открытым текстом, защитить его может лишь TLS.', 'Метод передаёт сам пароль; канал можно защитить, например TLS, шифрованием GSSAPI или SSH-туннелем.'),
        ('explanation', 'Какая привилегия базы данных разрешает подключение к ней?', NULL, NULL, 'По умолчанию CONNECT выдан псевдороли public, поэтому подключаться может любая роль с LOGIN.', 'По умолчанию CONNECT выдан псевдороли public; для входа также нужны LOGIN, успешная аутентификация и разрешённые подключения к базе.'),
        ('option', 'Что разрешает привилегия USAGE на схему?', 'Обращаться к объектам этой схемы', 'Находить объекты схемы по имени', 'Без неё имена объектов схемы не разрешаются; права на операции с объектами проверяются отдельно.', 'USAGE разрешает поиск объектов в схеме; права на операции с ними выдаются отдельно.'),
        ('option', 'Какие таблицы системного каталога общие для всего кластера?', '`pg_class`', '`pg_attribute`', 'Своя таблица в каждой базе.', 'Каталог столбцов локален для каждой базы.'),
        ('option', 'Какие таблицы системного каталога общие для всего кластера?', '`pg_proc`', '`pg_constraint`', 'Своя таблица в каждой базе.', 'Каталог ограничений локален для каждой базы.'),
        ('explanation', 'Какие таблицы системного каталога общие для всего кластера?', NULL, NULL, 'Базы данных, роли и табличные пространства описываются общими таблицами в pg_global; pg_class и pg_proc есть в каждой базе.', 'Базы данных, роли и табличные пространства описываются общими таблицами в pg_global; pg_attribute и pg_constraint есть в каждой базе.'),
        ('option', 'Какие параметры можно задать для табличного пространства командой ALTER TABLESPACE … SET?', '`work_mem`', '`temp_file_limit`', 'Задаётся для экземпляра, базы, роли или сеанса, но не для табличного пространства.', 'Ограничивает объём временных файлов процесса; параметром табличного пространства не является.'),
        ('option', 'Какие параметры можно задать для табличного пространства командой ALTER TABLESPACE … SET?', '`shared_buffers`', '`wal_buffers`', 'Задаётся для всего экземпляра и требует перезапуска.', 'Задаёт объём буферов WAL для всего экземпляра и требует перезапуска.'),
        ('option', 'Как PostgreSQL хранит файлы обычных таблиц и их индексов в одном табличном пространстве?', 'Все объекты базы — в одном файле', 'В общем файле для всей базы данных', 'Каждый объект хранится отдельно.', 'Общего файла всех таблиц базы нет.'),
        ('option', 'Как PostgreSQL хранит файлы обычных таблиц и их индексов в одном табличном пространстве?', 'Каждый объект — в своих отдельных файлах', 'В отдельных файлах для каждого объекта', 'В пользовательском табличном пространстве файлы лежат в подкаталогах версии сервера и базы данных.', 'У таблицы и каждого индекса собственный набор файлов; в пользовательском табличном пространстве они лежат в подкаталогах версии сервера и базы данных.'),
        ('option', 'Как PostgreSQL хранит файлы обычных таблиц и их индексов в одном табличном пространстве?', 'По одному файлу на схему', 'В общем файле для каждой схемы базы', 'Схемы на физическое хранение не влияют.', 'Схема логически объединяет объекты, но не их файлы.'),
        ('option', 'Как PostgreSQL хранит файлы обычных таблиц и их индексов в одном табличном пространстве?', 'Все таблицы пространства — в одном файле', 'В общем файле для всего табличного пространства', 'Каждый объект хранится отдельно.', 'Общего файла всего табличного пространства нет.'),
        ('explanation', 'Как PostgreSQL хранит файлы обычных таблиц и их индексов в одном табличном пространстве?', NULL, NULL, 'Каждая таблица и каждый индекс хранятся в собственных файлах — слоях, разбитых на сегменты по 1 ГБ; все объекты базы в один общий файл не складываются.', 'У обычной таблицы и каждого её индекса отдельные файлы слоёв и сегментов по 1 ГБ; представления и родительские секционированные таблицы собственного хранилища не имеют.'),
        ('option', 'Как называется первый сегмент основного слоя обычной журналируемой таблицы?', 'Числовым идентификатором без суффикса', 'Числовым filenode без суффикса', 'Суффикс имени слоя есть только у других слоёв; следующие сегменты получают окончания .1, .2 и далее.', 'Имя равно filenode, который может отличаться от OID таблицы. У первого сегмента основного слоя нет суффикса; следующие получают .1, .2 и далее.'),
        ('option', 'Значение уже вынесено в TOAST. UPDATE изменяет другой столбец, не затрагивая вынесенное значение; параметры хранения не менялись. Что происходит с вынесенным значением?', 'Новая версия строки ссылается на то же значение', NULL, 'Новая версия строки ссылается на то же значение в toast-таблице: у неё своя версионность, и это экономит место.', 'Новая версия строки сохраняет прежнюю внешнюю ссылку; неизменённое TOAST-значение повторно не копируется.'),
        ('option', 'Сервер собран с поддержкой lz4. Допишите имя параметра, чтобы задать lz4 методом сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```', '`''gzip''`', '`toast_compression`', 'Недопустимое значение.', 'Такого параметра конфигурации нет.'),
        ('option', 'Сервер собран с поддержкой lz4. Допишите имя параметра, чтобы задать lz4 методом сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```', '`''on''`', '`compression_method`', 'Это перечислимый параметр: допустимы pglz и lz4.', 'Такого параметра конфигурации нет.'),
        ('option', 'Сервер собран с поддержкой lz4. Допишите имя параметра, чтобы задать lz4 методом сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```', '`''zstd''`', '`wal_compression`', 'Для TOAST в PostgreSQL 16 недопустимое значение.', 'Управляет сжатием полностраничных образов в WAL, а не TOAST.'),
        ('option', 'Сервер собран с поддержкой lz4. Допишите имя параметра, чтобы задать lz4 методом сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```', '`''lz4''`', '`default_toast_compression`', 'Работает, если сервер собран с поддержкой lz4.', 'Задаёт метод сжатия TOAST по умолчанию; явная настройка COMPRESSION столбца имеет приоритет.'),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он запускается на Windows, но не на Linux', 'Для разбора требуется расширение на сервере', 'Такого ограничения нет: pgBadger написан на Perl и работает на разных ОС.', 'pgBadger разбирает файлы журнала; серверное расширение для этого не требуется.'),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он требует расширения pg_stat_statements для работы', 'Для построения отчёта нужен доступ к базе', 'pgBadger анализирует журнал сообщений.', 'Журналы можно анализировать без соединения с базой и при остановленном сервере.'),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он требует, чтобы размер базы был меньше 1 ГБ', 'Для анализа подходит журнал на любом языке', 'Такого предела размера базы у анализатора журналов нет.', 'Разбор опирается на текст сообщений, поэтому произвольная локаль не поддерживается.'),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он требует настроек журнала и английских сообщений', 'Для разбора нужен журнал на английском', 'Об этом нужно помнить, настраивая журнал: pgBadger разбирает определённый формат сообщений, поэтому нужны настройки журнала и сообщения на английском.', 'Нужны английские сообщения журнала; формат и состав журнала также настраивают для pgBadger.'),
        ('option', 'Какая привилегия нужна, чтобы роль могла создавать временные таблицы в базе данных?', 'TEMPORARY на базу данных', NULL, 'Имя схемы для временных объектов заранее неизвестно, поэтому привилегия вынесена на уровень базы.', 'TEMPORARY разрешает создание временных таблиц; сервер автоматически создаёт для сеанса временную схему. CREATE на public для этого не требуется.'),
        ('option', 'Привилегии по умолчанию для новых подпрограмм не меняли. Почему недостаточно один раз отозвать у PUBLIC EXECUTE на все существующие подпрограммы?', 'Новые подпрограммы снова получают EXECUTE для public', 'У новых подпрограмм PUBLIC получает EXECUTE', 'Для каждой новой подпрограммы public снова получает EXECUTE автоматически, если привилегии по умолчанию не меняли; остановить это можно командой ALTER DEFAULT PRIVILEGES.', 'Новые функции и процедуры получают EXECUTE для PUBLIC, пока через ALTER DEFAULT PRIVILEGES не изменены привилегии по умолчанию создающей их роли.'),
        ('option', 'Какие из перечисленных ролей входят в число предопределённых в PostgreSQL 16?', 'Роль pg_write_all_data', NULL, 'Даёт право изменять данные во всех таблицах.', 'Даёт права записи на таблицы, представления и последовательности и USAGE на схемы; не обходит RLS и не выдаёт SELECT.'),
        ('option', 'Эту строку помещают первой в pg_hba.conf. Допишите метод, чтобы запретить роли mallory TCP-подключения к любой базе с любого адреса:
```
# TYPE  DATABASE  USER     ADDRESS  METHOD
host    all       mallory  all      ___
```', 'trust', NULL, 'Безусловно разрешает подключение.', 'trust не проверяет личность клиента; LOGIN, CONNECT и прочие ограничения подключения сохраняются.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
